  `detail` longtext NOT NULL,
  `featured` tinyint(1) NOT NULL,
  `status` varchar(10) NOT NULL,
  `is_deleted` tinyint(1) NOT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `category_id` bigint NOT NULL,
  PRIMARY KEY (`id`),
  KEY `core_actualite_category_id_c0ce05d9_fk_core_cate` (`category_id`),
  KEY `core_actualite_slug_7746ec09` (`slug`),
  CONSTRAINT `core_actualite_category_id_c0ce05d9_fk_core_cate` FOREIGN KEY (`category_id`) REFERENCES `core_categorieactuality` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
