INSERT INTO `core_etapeprojet` VALUES (1,'Réalisation du TDR','<p>Un <strong data-end=\"178\" data-start=\"171\">TDR</strong>, abr&eacute;viation de <em data-end=\"216\" data-start=\"195\">Termes de R&eacute;f&eacute;rence</em>, est un <strong data-end=\"317\" data-start=\"225\">document fondamental qui d&eacute;crit clairement le but, la port&eacute;e et la structure d&rsquo;un projet</strong>. Il sert de <strong data-end=\"390\" data-start=\"330\">&laquo; cahier des charges &raquo; ou de feuille de route officielle</strong> pour tous les acteurs impliqu&eacute;s dans la r&eacute;alisation d&rsquo;un projet.</p>',1,'2026-10-15',0,'2026-02-09 12:42:44.219719','2026-02-09 12:49:20.229473',1,10),(2,'Organisation de l\'atelier multi acteurs','',0,'2025-07-09',0,'2026-02-10 12:48:59.973954','2026-02-10 12:48:59.973991',2,NULL),(3,'Appel à candidature pour la selection des PMEs','',0,'2025-09-01',0,'2026-02-10 12:48:59.974940','2026-02-10 12:48:59.974980',2,NULL),(4,'Organisation d\'une mission de présentation de l\'initiative','',0,'2025-02-17',0,'2026-02-10 13:08:11.294776','2026-02-10 13:08:11.294801',3,5),(5,'Organisation d\'une deuxième mission en Guinée','',0,'2025-05-13',0,'2026-02-10 13:08:11.295631','2026-02-10 13:08:11.295655',3,5),(6,'Organisation d\'un atelier multi acteurs','',0,'2025-12-05',0,'2026-02-10 13:08:11.296789','2026-02-10 13:08:11.296825',3,20),(7,'Organisation d\'une visite  d\'immersion de 16 cadres de differentes structures dans des structures tunisiennes similaires','',25,'2021-02-12',0,'2026-02-10 14:26:35.252332','2026-02-10 14:26:35.252355',4,NULL),(8,'Organisation d\'un voyage d\'études au CEPEX pour Trois Cadres','',25,'2023-02-28',0,'2026-02-10 14:26:35.253522','2026-02-10 14:26:35.253619',4,NULL),(9,'Participation de l\'AGUIPEX au SIAL de Paris','',25,'2023-10-19',0,'2026-02-10 14:26:35.254470','2026-02-10 14:26:35.254509',4,NULL),(10,'Elaboration des stratégies de communication des filières mangue et anacarde','',25,'2023-11-17',0,'2026-02-10 14:26:35.255206','2026-02-10 14:26:35.255227',4,NULL),(11,'Elaboration des Termes de réferences','',0,'2023-03-10',0,'2026-02-10 21:23:24.855413','2026-02-10 21:23:24.855443',5,5),(12,'Elaboration des Termes de réference pour le recrutement d\'un Cabinet pour la réalisation d\'une étude de faisabilité','',0,'2023-07-06',0,'2026-02-10 21:23:24.856393','2026-02-10 21:23:24.856425',5,5),(13,'Recrutement d\'un Cabinet pour l\'étude de faisabilité','',0,'2024-01-17',0,'2026-02-10 21:23:24.857187','2026-02-10 21:23:24.857222',5,20),(14,'Organisation d\'une enquête diagnostique des produits et services dans les 8 régions administratives de la Guinée','',0,'2025-12-23',0,'2026-02-10 21:41:32.322384','2026-02-10 21:41:32.322414',6,60);
