INSERT INTO `core_manifestationcommerciale` VALUES (10,'Salon International des Produits Agricoles de Guinée (SIPAG)','salon-international-des-produits-agricoles-de-guinee-sipag','<h2 data-end=\"592\" data-start=\"577\">🎯 Objectifs</h2>\r\n\r\n<ul data-end=\"828\" data-start=\"593\">\r\n	<li data-end=\"635\" data-start=\"593\">\r\n	<p data-end=\"635\" data-start=\"595\">Promouvoir les produits Made in Guinea</p>\r\n	</li>\r\n	<li data-end=\"697\" data-start=\"636\">\r\n	<p data-end=\"697\" data-start=\"638\">Mettre en relation producteurs, exportateurs et acheteurs</p>\r\n	</li>\r\n	<li data-end=\"737\" data-start=\"698\">\r\n	<p data-end=\"737\" data-start=\"700\">Attirer les investisseurs &eacute;trangers</p>\r\n	</li>\r\n	<li data-end=\"783\" data-start=\"738\">\r\n	<p data-end=\"783\" data-start=\"740\">Valoriser les cha&icirc;nes de valeur agricoles</p>\r\n	</li>\r\n	<li data-end=\"828\" data-start=\"784\">\r\n	<p data-end=\"828\" data-start=\"786\">Pr&eacute;senter l&rsquo;innovation agro-industrielle<br />\r\n	&nbsp;</p>\r\n\r\n	<h2 data-end=\"862\" data-start=\"835\">👥 Participants attendus</h2>\r\n	</li>\r\n	<li data-end=\"893\" data-start=\"863\">\r\n	<p data-end=\"893\" data-start=\"865\">250 entreprises guin&eacute;ennes</p>\r\n	</li>\r\n	<li data-end=\"925\" data-start=\"894\">\r\n	<p data-end=\"925\" data-start=\"896\">40 acheteurs internationaux</p>\r\n	</li>\r\n	<li data-end=\"957\" data-start=\"926\">\r\n	<p data-end=\"957\" data-start=\"928\">15 institutions financi&egrave;res</p>\r\n	</li>\r\n	<li data-end=\"977\" data-start=\"958\">\r\n	<p data-end=\"977\" data-start=\"960\">10 pays invit&eacute;s<br />\r\n	&nbsp;</p>\r\n\r\n	<h2 data-end=\"1043\" data-start=\"1017\">🏢 Secteurs repr&eacute;sent&eacute;s</h2>\r\n	</li>\r\n	<li data-end=\"1056\" data-start=\"1044\">\r\n	<p data-end=\"1056\" data-start=\"1046\">Anacarde</p>\r\n	</li>\r\n	<li data-end=\"1065\" data-start=\"1057\">\r\n	<p data-end=\"1065\" data-start=\"1059\">Caf&eacute;</p>\r\n	</li>\r\n	<li data-end=\"1075\" data-start=\"1066\">\r\n	<p data-end=\"1075\" data-start=\"1068\">Cacao</p>\r\n	</li>\r\n	<li data-end=\"1096\" data-start=\"1076\">\r\n	<p data-end=\"1096\" data-start=\"1078\">Fruits &amp; l&eacute;gumes</p>\r\n	</li>\r\n	<li data-end=\"1121\" data-start=\"1097\">\r\n	<p data-end=\"1121\" data-start=\"1099\">Produits transform&eacute;s</p>\r\n	</li>\r\n	<li data-end=\"1136\" data-start=\"1122\">\r\n	<p data-end=\"1136\" data-start=\"1124\">Emballages</p>\r\n	</li>\r\n	<li data-end=\"1158\" data-start=\"1137\">\r\n	<p data-end=\"1158\" data-start=\"1139\">Logistique export</p>\r\n	</li>\r\n</ul>','bientot_prevu','publier','2026-04-20','2026-04-26','Stade de Nongo','GUINEE',0,'2026-02-11 01:36:42.787312','2026-02-11 01:43:02.391768','<ul data-end=\"1446\" data-start=\"1312\">\r\n	<li data-end=\"1352\" data-start=\"1312\">\r\n	<p data-end=\"1352\" data-start=\"1314\">&Ecirc;tre l&eacute;galement enregistr&eacute; en Guin&eacute;e</p>\r\n	</li>\r\n	<li data-end=\"1384\" data-start=\"1353\">\r\n	<p data-end=\"1384\" data-start=\"1355\">Avoir un produit exportable</p>\r\n	</li>\r\n	<li data-end=\"1417\" data-start=\"1385\">\r\n	<p data-end=\"1417\" data-start=\"1387\">Respecter les normes qualit&eacute;</p>\r\n	</li>\r\n	<li data-end=\"1446\" data-start=\"1418\">\r\n	<p data-end=\"1446\" data-start=\"1420\">Payer les frais de stand</p>\r\n	</li>\r\n	<li data-end=\"1511\" data-start=\"1483\">\r\n	<p data-end=\"1511\" data-start=\"1485\">Standard : 5 000 000 GNF</p>\r\n	</li>\r\n	<li data-end=\"1539\" data-start=\"1512\">\r\n	<p data-end=\"1539\" data-start=\"1514\">Premium : 8 000 000 GNF</p>\r\n	</li>\r\n	<li data-end=\"1583\" data-start=\"1540\">\r\n	<p data-end=\"1583\" data-start=\"1542\">Pavillon international : 12 000 000 GNF</p>\r\n	</li>\r\n</ul>'),(11,'Expo Mines & Industries Guinée (EMIG)','expo-mines-industries-guinee-emig','<h2 data-end=\"447\" data-start=\"430\">🎯 Objectifs</h2>\r\n\r\n<ul data-end=\"682\" data-start=\"448\">\r\n	<li data-end=\"505\" data-start=\"448\">\r\n	<p data-end=\"505\" data-start=\"450\">Promouvoir les opportunit&eacute;s industrielles et mini&egrave;res</p>\r\n	</li>\r\n	<li data-end=\"558\" data-start=\"506\">\r\n	<p data-end=\"558\" data-start=\"508\">Connecter entreprises locales et multinationales</p>\r\n	</li>\r\n	<li data-end=\"605\" data-start=\"559\">\r\n	<p data-end=\"605\" data-start=\"561\">D&eacute;velopper les partenariats technologiques</p>\r\n	</li>\r\n	<li data-end=\"645\" data-start=\"606\">\r\n	<p data-end=\"645\" data-start=\"608\">Encourager la transformation locale</p>\r\n	</li>\r\n	<li data-end=\"682\" data-start=\"646\">\r\n	<p data-end=\"682\" data-start=\"648\">Faciliter l&rsquo;acc&egrave;s au financement</p>\r\n	</li>\r\n</ul>\r\n\r\n<hr data-end=\"687\" data-start=\"684\" />\r\n<h2 data-end=\"718\" data-start=\"689\">👥 Participants attendus</h2>\r\n\r\n<ul data-end=\"821\" data-start=\"719\">\r\n	<li data-end=\"749\" data-start=\"719\">\r\n	<p data-end=\"749\" data-start=\"721\">180 entreprises nationales</p>\r\n	</li>\r\n	<li data-end=\"776\" data-start=\"750\">\r\n	<p data-end=\"776\" data-start=\"752\">65 soci&eacute;t&eacute;s &eacute;trang&egrave;res</p>\r\n	</li>\r\n	<li data-end=\"797\" data-start=\"777\">\r\n	<p data-end=\"797\" data-start=\"779\">25 investisseurs</p>\r\n	</li>\r\n	<li data-end=\"821\" data-start=\"798\">\r\n	<p data-end=\"821\" data-start=\"800\">12 pays repr&eacute;sent&eacute;s</p>\r\n	</li>\r\n</ul>\r\n\r\n<hr data-end=\"826\" data-start=\"823\" />\r\n<h2 data-end=\"846\" data-start=\"828\">🧮 Superficie</h2>\r\n\r\n<p data-end=\"856\" data-start=\"847\">18 500 m&sup2;</p>\r\n\r\n<hr data-end=\"861\" data-start=\"858\" />\r\n<h2 data-end=\"891\" data-start=\"863\">🏢 Secteurs repr&eacute;sent&eacute;s</h2>\r\n\r\n<ul data-end=\"1045\" data-start=\"892\">\r\n	<li data-end=\"925\" data-start=\"892\">\r\n	<p data-end=\"925\" data-start=\"894\">Mines &amp; ressources naturelles</p>\r\n	</li>\r\n	<li data-end=\"953\" data-start=\"926\">\r\n	<p data-end=\"953\" data-start=\"928\">&Eacute;quipements industriels</p>\r\n	</li>\r\n	<li data-end=\"965\" data-start=\"954\">\r\n	<p data-end=\"965\" data-start=\"956\">&Eacute;nergie</p>\r\n	</li>\r\n	<li data-end=\"992\" data-start=\"966\">\r\n	<p data-end=\"992\" data-start=\"968\">Transport &amp; logistique</p>\r\n	</li>\r\n	<li data-end=\"1028\" data-start=\"993\">\r\n	<p data-end=\"1028\" data-start=\"995\">Services num&eacute;riques industriels</p>\r\n	</li>\r\n	<li data-end=\"1045\" data-start=\"1029\">\r\n	<p data-end=\"1045\" data-start=\"1031\">Construction</p>\r\n	</li>\r\n</ul>','selection_terminee','publier','2026-02-24','2026-02-27','Palais du peuple de Conakry','GUINEE',0,'2026-02-11 01:40:08.683679','2026-02-11 11:31:50.053882','<h2 data-end=\"1207\" data-start=\"1172\">🎫 Conditions de participation</h2>\r\n\r\n<ul data-end=\"1369\" data-start=\"1208\">\r\n	<li data-end=\"1238\" data-start=\"1208\">\r\n	<p data-end=\"1238\" data-start=\"1210\">&Ecirc;tre enregistr&eacute; l&eacute;galement</p>\r\n	</li>\r\n	<li data-end=\"1286\" data-start=\"1239\">\r\n	<p data-end=\"1286\" data-start=\"1241\">Disposer d&rsquo;un service ou produit industriel</p>\r\n	</li>\r\n	<li data-end=\"1329\" data-start=\"1287\">\r\n	<p data-end=\"1329\" data-start=\"1289\">Respecter les normes environnementales</p>\r\n	</li>\r\n	<li data-end=\"1369\" data-start=\"1330\">\r\n	<p data-end=\"1369\" data-start=\"1332\">Validation du comit&eacute; d&rsquo;organisation</p>\r\n	</li>\r\n</ul>\r\n\r\n<hr data-end=\"1374\" data-start=\"1371\" />\r\n<h2 data-end=\"1407\" data-start=\"1376\">💰 Co&ucirc;t du stand (exemple)</h2>\r\n\r\n<ul data-end=\"1503\" data-start=\"1408\">\r\n	<li data-end=\"1436\" data-start=\"1408\">\r\n	<p data-end=\"1436\" data-start=\"1410\">Standard : 9 000 000 GNF</p>\r\n	</li>\r\n	<li data-end=\"1465\" data-start=\"1437\">\r\n	<p data-end=\"1465\" data-start=\"1439\">Premium : 15 000 000 GNF</p>\r\n	</li>\r\n	<li data-end=\"1503\" 