INSERT INTO `core_procedureglobale` VALUES (1,'Formalité','Avoir un RCCM (APIP)\r\nAvoir un NIF (APIP)\r\nÊtre enregistré dans la base de donnée AGUIPEX','publier',0,'2025-04-07 11:04:42.684091','2025-04-07 11:04:42.684156'),(2,'DDE','Recours à la plateforme du Guichet  Unique\r\nLettre de rapatriement des devises','publier',0,'2025-04-07 11:08:12.258288','2025-04-07 11:08:12.258332'),(3,'Formalité en Douane','Formalité en Douane','publier',0,'2025-04-07 11:09:10.223864','2025-05-07 14:42:52.874306'),(4,'Certificat Technique et Conventionnel','Certificat d\'analyse à ONCQ et Certificat Conventionnel à AGUIPEX','publier',0,'2025-04-07 11:10:14.224182','2025-05-07 14:43:05.644042'),(5,'PROCEDURE D\'EXPORTATION DES PRODUITS GUINEENNE','L\'exercice de l\'activité d\'exportation des produits nécessite l\'immatriculation au registre du commerce conformément aux règlementations en vigueur.\r\nles opérations d\'exportation peuvent être effectuées par toute personne exerçant légalement une activité économique en République de Guinée.\r\nToute exportation doit être accompagner des documents ci-dessous :\r\n-Un certificat d\'analyse suite au prélèvement d\'échantillons;\r\n-Un certificat de contrôle de qualité;\r\n-Un certificat phytosanitaire,\r\nUn certificat d\'origine;\r\n- La déclaration descriptive d\'exportation et d\'importation( DDE-DDI),','publier',1,'2025-04-14 10:54:59.778417','2025-04-14 11:16:10.845768');
/*!40000 ALTER TABLE `core_procedureglobale` ENABLE KEYS */;
UNLOCK TABLES;

