/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `core_produit` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `title` varchar(191) NOT NULL,
  `description` longtext,
  `image` varchar(100) DEFAULT NULL,
  `fiche_produit` varchar(100) DEFAULT NULL,
  `featured` tinyint(1) NOT NULL,
  `status` varchar(10) NOT NULL,
  `is_deleted` tinyint(1) NOT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `couleur` varchar(20) NOT NULL,
  `entreprise_id` bigint DEFAULT NULL,
  `pour_site` tinyint(1) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `core_produit_entreprise_id_038eb7a4_fk_core_entreprise_id` (`entreprise_id`),
  CONSTRAINT `core_produit_entreprise_id_038eb7a4_fk_core_entreprise_id` FOREIGN KEY (`entreprise_id`) REFERENCES `core_entreprise` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
