INSERT INTO `core_produitentreprise` VALUES (1,'Le 𝐜𝐡𝐨𝐜𝐨𝐥𝐚𝐭 𝐩𝐨𝐮𝐫 𝐜𝐡𝐚𝐪𝐮𝐞 𝐟𝐨𝐫𝐦𝐞 𝐝’𝐚𝐦𝐨𝐮𝐫 💝','𝐧 𝐜𝐡𝐨𝐜𝐨𝐥𝐚𝐭 𝐩𝐨𝐮𝐫 𝐜𝐡𝐚𝐪𝐮𝐞 𝐟𝐨𝐫𝐦𝐞 𝐝’𝐚𝐦𝐨𝐮𝐫 💝\r\nPartenaire de vie, collègue, ami(e), personne que vous admirez…\r\nIl y a toujours une bonne raison d’offrir du chocolat Zeïna Cacao.\r\nCette Saint-Valentin, pensez large, aimez vrai 🤎\r\n𝐙𝐞𝐢̈𝐧𝐚 𝐂𝐚𝐜𝐚𝐨 – 𝐂𝐨𝐧𝐬𝐨𝐦𝐦𝐨𝐧𝐬 𝐥𝐞 𝐜𝐡𝐨𝐜𝐨𝐥𝐚𝐭 𝐝𝐞 𝐜𝐡𝐞𝐳 𝐧𝐨𝐮𝐬 🇬🇳','ProduitsEntreprise/628311354_1803395640775235_41155521ss46941939699_n.jpg','publier',0,'2026-02-11 01:49:01.888261','2026-02-11 01:49:01.888295',4,2),(2,'𝐥𝐚 𝐩𝐨𝐮𝐝𝐫𝐞 𝐝𝐞 𝐜𝐚𝐜𝐚𝐨 ? 🍫☕','D𝐞 𝐯𝐨𝐮𝐬 𝐚̀ 𝐧𝐨𝐮𝐬, 𝐩𝐨𝐮𝐫𝐪𝐮𝐨𝐢 𝐜𝐡𝐨𝐢𝐬𝐢𝐫 𝐥𝐚 𝐩𝐨𝐮𝐝𝐫𝐞 𝐝𝐞 𝐜𝐚𝐜𝐚𝐨 ? 🍫☕\r\n1️⃣ Elle est 100 % naturelle, sans mélange, sans chimie.\r\n2️⃣ Elle donne de l’énergie et fait du bien au corps et à l’esprit.\r\n3️⃣ Elle est polyvalente : petit-déjeuner, chocolat chaud, recettes, pâtisserie…\r\nUn seul produit, plusieurs plaisirs 😌🍫\r\nAlors passez en boutique ou commandez dès maintenant 📞\r\n𝐙𝐞𝐢̈𝐧𝐚 𝐂𝐚𝐜𝐚𝐨 – 𝐂𝐨𝐧𝐬𝐨𝐦𝐦𝐨𝐧𝐬 𝐥𝐞 𝐜𝐡𝐨𝐜𝐨𝐥𝐚𝐭 𝐝𝐞 𝐜𝐡𝐞𝐳 𝐧𝐨𝐮𝐬 🇬🇳','ProduitsEntreprise/622255819_1793533505094782_5063375908012698566_n.jpg','publier',0,'2026-02-11 01:51:00.276734','2026-02-11 01:51:00.276765',4,2),(3,'Fonio Friday','🌾 Le fonio vous attend 🤗 chez nos #restaurants 👩‍🍳 partenaires tout à l’heure 🕰️.','ProduitsEntreprise/616143300_1285958086902fff499_979875429733258172_n.jpg','publier',0,'2026-02-11 01:53:46.078488','2026-02-11 01:53:46.078522',5,3);
