INSERT INTO `core_valeur` VALUES (1,'IconeValeur/2361634.png','Valeur','1','<p>Nous cr&eacute;ons de l&rsquo;impact en donnant du sens &agrave; chaque action</p>','publier',1,'2025-05-06 14:30:42.571455','2026-02-10 22:37:39.556527'),(2,'IconeValeur/10717972.png','Excellence','5','<p>Viser l&rsquo;excellence, c&rsquo;est refuser la m&eacute;diocrit&eacute;.</p>','publier',0,'2025-05-07 10:32:30.399529','2026-02-10 22:36:15.728787'),(3,'IconeValeur/images-removebg-preview.png','Esprit d’équipe','4','<p>Unir les forces pour atteindre un objectif commun, Ensemble On n&#39;ira plus loin</p>','publier',0,'2025-05-07 10:32:57.796002','2026-02-10 22:34:39.688525'),(4,'IconeValeur/icone-removebg-preview.png','Responsabilité','3','<p>Nous assumons nos engagements avec rigueur.</p>','publier',0,'2025-05-07 10:33:27.125854','2026-02-10 22:29:17.389648'),(5,'IconeValeur/EQUITE_TUREx8N_JVr8O8q.webp','Intégrité','2','<p>La transparence guide toutes nos d&eacute;cisions.</p>','publier',0,'2025-05-07 10:34:14.326302','2026-02-10 22:12:03.093634'),(6,'IconeValeur/PARTENARIAT_HwwD7XC.webp','Respect','1','<p>Nous employons des mots et des gestes courtois dans nos interactions quotidiennes.</p>','publier',0,'2025-05-15 14:32:07.870892','2026-02-10 22:11:51.574573');
