CREATE TABLE `userauths_user` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `password` varchar(128) NOT NULL,
  `last_login` datetime(6) DEFAULT NULL,
  `is_superuser` tinyint(1) NOT NULL,
  `first_name` varchar(150) NOT NULL,
  `last_name` varchar(150) NOT NULL,
  `is_staff` tinyint(1) NOT NULL,
  `is_active` tinyint(1) NOT NULL,
  `date_joined` datetime(6) NOT NULL,
  `username` varchar(100) NOT NULL,
  `email` varchar(254) DEFAULT NULL,
  `full_name` varchar(100) NOT NULL,
  `otp` varchar(100) DEFAULT NULL,
  `refresh_token` varchar(1000) DEFAULT NULL,
  `occupation` varchar(150) NOT NULL,
  `status` tinyint(1) NOT NULL,
  `entreprise` varchar(150) DEFAULT NULL,
  `phone` varchar(200) DEFAULT NULL,
  `cellule` varchar(150) NOT NULL,
  `departement` varchar(150) NOT NULL,
  `grade` varchar(150) NOT NULL,
  `profile_picture` varchar(100) DEFAULT NULL,
  `profile_picture_url` varchar(200) DEFAULT NULL,
  `role` varchar(150) NOT NULL,
  `est_employer` tinyint(1) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=374 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
